/* style.css - Online Voting System Custom Styles */

/* ===== Base & Reset ===== */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  line-height: 1.6;
  color: #333;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ===== Smooth Scrolling ===== */
html {
  scroll-behavior: smooth;
}

/* ===== Typography Enhancements ===== */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.3;
}

.display-4 {
  font-size: clamp(2rem, 5vw, 3.5rem);
}

/* ===== Navbar Customization ===== */
.navbar {
  padding: 0.75rem 0;
}

.navbar-brand {
  font-size: 1.25rem;
  letter-spacing: -0.5px;
}

.nav-link {
  font-weight: 500;
  padding: 0.5rem 1rem !important;
  transition: color 0.2s ease;
}

.nav-link:hover,
.nav-link.active {
  color: #fff !important;
  opacity: 0.9;
}

/* ===== Hero Section ===== */
.bg-gradient {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%) !important;
}

.hero-cta .btn {
  padding: 0.75rem 2rem;
  font-weight: 600;
  border-radius: 50px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.hero-cta .btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

/* ===== Stats Section ===== */
.stats-card {
  background: #f8f9fa;
  border-radius: 12px;
  padding: 1rem;
  transition: transform 0.2s ease;
}

.stats-card:hover {
  transform: translateY(-3px);
  background: #fff;
  box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.1);
}

.stats-card h3 {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
}

.stats-card small {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* ===== Candidate Cards ===== */
.card {
  border: none;
  border-radius: 16px;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  background: #fff;
}

.card:hover {
  transform: translateY(-8px);
  box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.12) !important;
}

.card-img-top {
  height: 200px;
  object-fit: cover;
  background: linear-gradient(135deg, #667eea, #764ba2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 3rem;
  font-weight: bold;
}

.card-body {
  padding: 1.5rem;
}

.card-title {
  font-size: 1.1rem;
  margin-bottom: 0.25rem;
}

.card-text {
  font-size: 0.95rem;
  color: #6c757d;
}

/* ===== Candidate Avatar Placeholder ===== */
.avatar-placeholder {
  width: 100%;
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  color: white;
  font-weight: 600;
}

/* ===== Buttons ===== */
.btn {
  font-weight: 600;
  padding: 0.5rem 1.25rem;
  border-radius: 10px;
  transition: all 0.2s ease;
}

.btn-primary {
  background: linear-gradient(135deg, #667eea, #764ba2);
  border: none;
}

.btn-primary:hover {
  background: linear-gradient(135deg, #5568d3, #653c96);
  transform: translateY(-1px);
  box-shadow: 0 0.5rem 1rem rgba(102, 126, 234, 0.4);
}

.btn-outline-light:hover {
  background: rgba(255, 255, 255, 0.15);
  transform: translateY(-1px);
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none !important;
}

/* ===== How It Works Section ===== */
.step-icon {
  width: 70px;
  height: 70px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  font-size: 1.5rem;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.1);
}

.step-icon.bg-primary { background: linear-gradient(135deg, #667eea, #764ba2) !important; }
.step-icon.bg-success { background: linear-gradient(135deg, #11998e, #38ef7d) !important; }
.step-icon.bg-info { background: linear-gradient(135deg, #4facfe, #00f2fe) !important; }

/* ===== Modals ===== */
.modal-content {
  border: none;
  border-radius: 20px;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.2);
}

.modal-header {
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
  border-radius: 20px 20px 0 0 !important;
}

.modal-footer {
  border-top: 1px solid rgba(0, 0, 0, 0.05);
  border-radius: 0 0 20px 20px !important;
}

/* ===== Footer ===== */
footer a {
  transition: color 0.2s ease, opacity 0.2s ease;
}

footer a:hover {
  color: #fff !important;
  opacity: 1;
}

footer .social-link {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.1);
  margin-right: 0.5rem;
  transition: background 0.2s ease;
}

footer .social-link:hover {
  background: rgba(255, 255, 255, 0.25);
}

/* ===== Utilities ===== */
.hover-lift {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.hover-lift:hover {
  transform: translateY(-4px);
  box-shadow: 0 0.75rem 1.5rem rgba(0, 0, 0, 0.1) !important;
}

.opacity-75 { opacity: 0.75 !important; }
.opacity-90 { opacity: 0.9 !important; }

/* ===== Animations ===== */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-fade-in {
  animation: fadeInUp 0.5s ease forwards;
}

/* Staggered animation delays for cards */
.row.g-4 > div:nth-child(1) { animation-delay: 0.1s; }
.row.g-4 > div:nth-child(2) { animation-delay: 0.2s; }
.row.g-4 > div:nth-child(3) { animation-delay: 0.3s; }
.row.g-4 > div:nth-child(4) { animation-delay: 0.4s; }

/* ===== Responsive Adjustments ===== */
@media (max-width: 768px) {
  .navbar-collapse {
    padding: 1rem;
    background: rgba(102, 126, 234, 0.98);
    border-radius: 12px;
    margin-top: 0.5rem;
  }
  
  .display-4 {
    font-size: 2.25rem;
  }
  
  .card-img-top {
    height: 180px;
  }
  
  .stats-card h3 {
    font-size: 1.5rem;
  }
}

@media (max-width: 480px) {
  .btn-lg {
    padding: 0.6rem 1.5rem;
    font-size: 0.95rem;
  }
  
  .modal-dialog {
    margin: 1rem;
  }
}

/* ===== Focus States for Accessibility ===== */
.btn:focus-visible,
.form-control:focus-visible,
.nav-link:focus-visible {
  outline: 3px solid rgba(102, 126, 234, 0.5);
  outline-offset: 2px;
}

/* ===== Print Styles (for demo receipts) ===== */
@media print {
  body * {
    visibility: hidden;
  }
  #printable-receipt,
  #printable-receipt * {
    visibility: visible;
  }
  #printable-receipt {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
  }
}

/* ===== Dark Mode Support (Optional) ===== */
@media (prefers-color-scheme: dark) {
  body {
    background-color: #121212;
    color: #f8f9fa;
  }
  
  .card,
  .modal-content,
  .stats-card {
    background-color: #1e1e1e;
    color: #f8f9fa;
  }
  
  .card-text,
  .text-muted {
    color: #adb5bd !important;
  }
  
  .form-control {
    background-color: #2d2d2d;
    border-color: #444;
    color: #fff;
  }
  
  .form-control::placeholder {
    color: #888;
  }
}
